entries[66476] = { ["name"] = "Reichhaltiges Festmahl", ["text"] = "5 Meter Reichweite\nWirken in 1 sek.\nErrichtet ein reichhaltiges Festmahl, um eine sehr hungrige Gruppe zu sättigen. Stellt im Verlauf von 30 sec pro Sekunde 4% Gesundheit und Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sekunden lang mit Essen verbringt, werdet Ihr satt und erhaltet 1 Stunde lang [floor(cond([Quellwert]([Quellwert], 15), [Quellwert] - 15, 0) * 1.108) + 8] Angriffskraft, [floor(cond([Quellwert]([Quellwert], 15), [Quellwert] - 15, 0) * 0.6616) + 4] Zaubermacht und [floor(cond([Quellwert]([Quellwert], 15), [Quellwert] - 15, 0) * 0.554) + 4] Ausdauer.", ["unresolvedValues"] = true }
